// splines-eqdsk: a tokamak equilibrium as a spline field.
//
// A tokamak equilibrium is stored by the codes that compute it as an EQDSK
// file: the poloidal magnetic flux psi(R, Z) on a uniform grid in the
// poloidal plane. PCMS reads the file and turns the flux into a field in a
// bicubic spline space, which, unlike the linear (Lagrange) spaces, is smooth
// enough to differentiate: the gradient of psi gives the poloidal magnetic
// field,
//     B_R = -(1/R) dpsi/dZ,    B_Z = (1/R) dpsi/dR.
//
// The file here is generated by make_eqdsk.py from an analytic Solov'ev
// equilibrium,
//     psi(R, Z) = psi_axis + A (R^2 - R0^2)^2 + B Z^2,
// so everything the example computes from the file is compared with the exact
// answer. The tiny file (25 x 33 points) is there for the data format, not
// for the physics.
//
// What you will see, in order:
//   1. reading the file: the grid, and a field in a spline space on it;
//   2. the gradient of the field, and the magnetic field from it;
//   3. the magnetic axis, found as the zero of the gradient;
//   4. a flux surface, sampled by bisection along rays from the axis;
//   5. the checks: psi on the axis, B against the analytic field, B
//      divergence-free on the surface.
//
// Usage: fields_splines_eqdsk <path to solovev.eqdsk>

#include <pcms/field/eqdsk_field.hpp>
#include <pcms/field/query_points.hpp>
#include <pcms/utility/coordinate_systems/cylindrical.hpp>

#include <Kokkos_Core.hpp>

#include "example_utils.hpp"

#include <algorithm>
#include <array>
#include <cmath>
#include <cstdio>
#include <limits>
#include <memory>
#include <string>
#include <vector>

namespace
{
using pcms::Real;

// The equilibrium of make_eqdsk.py, for the comparisons.
constexpr Real R0 = 1.7;
constexpr Real MinorRadius = 0.5;
constexpr Real Kappa = 1.6;
constexpr Real PsiAxis = -0.4;
constexpr Real PsiBoundary = 0.6;
constexpr Real OuterShift = (R0 + MinorRadius) * (R0 + MinorRadius) - R0 * R0;
constexpr Real CoefficientA =
  (PsiBoundary - PsiAxis) / (OuterShift * OuterShift);
constexpr Real CoefficientB =
  (PsiBoundary - PsiAxis) / ((Kappa * MinorRadius) * (Kappa * MinorRadius));

// the poloidal field of the exact psi
Real ExactBR(Real r, Real z)
{
  return -2.0 * CoefficientB * z / r;
}
Real ExactBZ(Real r, Real)
{
  return 4.0 * CoefficientA * (r * r - R0 * R0);
}

// A bicubic spline reproduces the quartic psi to about h^4 times its fourth
// derivative / 77 (1e-6 here), and its gradient to one order less. The axis is
// at a node of the grid, where the spline is more accurate than elsewhere. The
// measured errors are printed.
constexpr Real AxisTol = 1e-4;
constexpr Real PsiAxisTol = 1e-7;
constexpr Real FieldTol = 1e-4;
constexpr Real SurfaceTol = 1e-9;
constexpr Real OutboardTol = 1e-5;
// B is divergence-free up to the symmetry of the mixed second derivatives of
// the spline, which a tensor-product spline of this psi has to rounding; the
// finite difference with a step of 1e-3 multiplies that by 1e3.
constexpr Real DivergenceTol = 1e-8;
constexpr Real Step = 1e-3;

// Evaluates psi and its gradient at points of the (R, Z) plane.
class Flux
{
public:
  Flux(const pcms::Function<Real>& psi,
       std::shared_ptr<const pcms::CoordinateSystem> system)
    : psi_(psi),
      system_(std::move(system)),
      query_(psi.GetSpace().GetGeometry()),
      // The gradient is a covector with physical components in the system of
      // the space: (dpsi/dR, dpsi/dZ). The view that an evaluation writes to
      // is tagged with the basis the caller expects, and PCMS refuses a
      // mismatch.
      gradient_basis_{system_, pcms::ComponentScaling::Physical,
                      pcms::values::Covector}
  {
  }

  // psi at the points (rows of `points`: R, Z)
  example::HostMatrix Psi(const example::HostMatrix& points)
  {
    query_.Locate(example::Points(system_, example::ToDevice(points)));
    example::DeviceMatrix out("psi", points.extent(0), 1);
    query_.Evaluate(psi_, example::Output(psi_.GetData().GetValueBasis(), out));
    return example::ToHost(out);
  }

  // (dpsi/dR, dpsi/dZ) at the points
  example::HostMatrix Gradient(const example::HostMatrix& points)
  {
    query_.Locate(example::Points(system_, example::ToDevice(points)));
    example::DeviceMatrix out("gradient", points.extent(0), 2);
    query_.Evaluate(psi_, example::Output(gradient_basis_, out),
                    pcms::DifferentialOperator::Gradient);
    return example::ToHost(out);
  }

private:
  const pcms::Function<Real>& psi_;
  std::shared_ptr<const pcms::CoordinateSystem> system_;
  pcms::QueryPoints query_;
  pcms::ValueBasis gradient_basis_;
};

// The points of `base` moved by (dr, dz).
example::HostMatrix Shifted(const example::HostMatrix& base, Real dr, Real dz)
{
  example::HostMatrix shifted("shifted", base.extent(0), 2);
  for (std::size_t i = 0; i < base.extent(0); ++i) {
    shifted(i, 0) = base(i, 0) + dr;
    shifted(i, 1) = base(i, 1) + dz;
  }
  return shifted;
}
} // namespace

int main(int argc, char** argv)
{
  Kokkos::ScopeGuard kokkos(argc, argv);
  example::Report report;
  if (argc < 2) {
    std::printf("usage: %s <path to solovev.eqdsk>\n", argv[0]);
    return 2;
  }
  {
    // -------------------------------------------------------------------
    // 1. Reading the file
    //
    // MakeEQDSKField reads the file and returns the data of the file (the
    // grid, the flux, and the flux at the axis and at the boundary), a bicubic
    // spline space on a uniform grid in cylindrical (R, Z) coordinates, and a
    // field holding psi. That field can be stored and communicated but not
    // evaluated, so its values are copied to a Function of the space, which
    // can be evaluated.
    const auto eqdsk = pcms::MakeEQDSKField(argv[1]);
    const auto& data = eqdsk.data;
    std::printf("EQDSK: %d x %d points, R in [%.2f, %.2f], Z in [%.2f, %.2f]\n",
                data.GetNW(), data.GetNH(), data.GetRMin(), data.GetRMax(),
                data.GetZMin(), data.GetZMax());
    auto psi = eqdsk.space->CreateFunction<Real>("psi");
    psi.SetDOFHolderData(eqdsk.field.GetDOFHolderData());
    Flux flux(psi, eqdsk.space->GetCoordinateSystem());

    // psi on the axis and at the boundary, from the file
    const auto psi_grid = Kokkos::create_mirror_view_and_copy(
      pcms::HostMemorySpace(), data.psi_grid);
    const Real psi_axis = psi_grid(0);
    const Real psi_boundary = psi_grid(psi_grid.extent(0) - 1);

    // -------------------------------------------------------------------
    // 2. The gradient, and the magnetic field
    //
    // The spline space supports the Gradient operator: evaluating with it
    // gives (dpsi/dR, dpsi/dZ) in place of psi. The poloidal field follows
    // from it. Compare it with the exact one on a 6 x 6 set of probes.
    example::HostMatrix probes("probes", 36, 2);
    for (int i = 0; i < 6; ++i) {
      for (int j = 0; j < 6; ++j) {
        probes(6 * i + j, 0) = 1.45 + 0.06 * i;
        probes(6 * i + j, 1) = -0.5 + 0.2 * j;
      }
    }
    const auto grad = flux.Gradient(probes);
    Real field_error = 0.0;
    for (std::size_t i = 0; i < probes.extent(0); ++i) {
      const Real r = probes(i, 0), z = probes(i, 1);
      field_error =
        std::fmax(field_error, std::hypot(-grad(i, 1) / r - ExactBR(r, z),
                                          grad(i, 0) / r - ExactBZ(r, z)));
    }
    std::printf("poloidal field from the gradient: error %.3e\n", field_error);

    // -------------------------------------------------------------------
    // 3. The magnetic axis
    //
    // The axis is the minimum of psi, where its gradient vanishes. Newton's
    // method on the gradient, with the Jacobian (the Hessian of psi) by
    // central differences of the gradient, starts from the smallest value of
    // psi on the grid and converges in a few steps.
    const auto psizr =
      Kokkos::create_mirror_view_and_copy(pcms::HostMemorySpace(), data.PSIZR);
    int best_i = 0, best_j = 0;
    for (int j = 0; j < data.GetNH(); ++j) {
      for (int i = 0; i < data.GetNW(); ++i) {
        if (psizr(data.GetPsiIndex(i, j)) <
            psizr(data.GetPsiIndex(best_i, best_j))) {
          best_i = i;
          best_j = j;
        }
      }
    }
    example::HostMatrix axis("axis", 1, 2);
    axis(0, 0) = data.GetR(best_i);
    axis(0, 1) = data.GetZ(best_j);
    Real residual = 0.0;
    int iterations = 0;
    for (; iterations < 20; ++iterations) {
      const auto g = flux.Gradient(axis);
      residual = std::hypot(g(0, 0), g(0, 1));
      if (residual < 1e-12) {
        break;
      }
      const auto right = flux.Gradient(Shifted(axis, Step, 0.0));
      const auto left = flux.Gradient(Shifted(axis, -Step, 0.0));
      const auto up = flux.Gradient(Shifted(axis, 0.0, Step));
      const auto down = flux.Gradient(Shifted(axis, 0.0, -Step));
      const Real h_rr = (right(0, 0) - left(0, 0)) / (2.0 * Step);
      const Real h_rz = (up(0, 0) - down(0, 0)) / (2.0 * Step);
      const Real h_zr = (right(0, 1) - left(0, 1)) / (2.0 * Step);
      const Real h_zz = (up(0, 1) - down(0, 1)) / (2.0 * Step);
      const Real det = h_rr * h_zz - h_rz * h_zr;
      axis(0, 0) -= (h_zz * g(0, 0) - h_rz * g(0, 1)) / det;
      axis(0, 1) -= (-h_zr * g(0, 0) + h_rr * g(0, 1)) / det;
    }
    const Real psi_at_axis = flux.Psi(axis)(0, 0);
    std::printf("magnetic axis: R = %.6f, Z = %.6f after %d Newton steps "
                "(|grad psi| = %.1e), psi = %.8f\n",
                axis(0, 0), axis(0, 1), iterations, residual, psi_at_axis);

    // -------------------------------------------------------------------
    // 4. A flux surface
    //
    // The surface halfway from the axis to the boundary in psi: for each of 64
    // directions, the point on the ray from the axis where psi crosses that
    // value, found by bisection. psi increases along every ray from the axis
    // and the rays end at the edge of the grid, where psi is larger, so the
    // bracket is known. All 64 bisections advance together, one evaluation
    // of 64 points per step.
    const Real psi_target = psi_axis + 0.5 * (psi_boundary - psi_axis);
    constexpr int NumRays = 64;
    example::HostMatrix lo("lo", NumRays, 1), hi("hi", NumRays, 1);
    example::HostMatrix direction("direction", NumRays, 2);
    for (int k = 0; k < NumRays; ++k) {
      const Real angle = 2.0 * 3.14159265358979323846 * k / NumRays;
      direction(k, 0) = std::cos(angle);
      direction(k, 1) = std::sin(angle);
      Real reach = std::numeric_limits<Real>::max();
      if (direction(k, 0) > 1e-12) {
        reach =
          std::min(reach, (data.GetRMax() - axis(0, 0)) / direction(k, 0));
      } else if (direction(k, 0) < -1e-12) {
        reach =
          std::min(reach, (data.GetRMin() - axis(0, 0)) / direction(k, 0));
      }
      if (direction(k, 1) > 1e-12) {
        reach =
          std::min(reach, (data.GetZMax() - axis(0, 1)) / direction(k, 1));
      } else if (direction(k, 1) < -1e-12) {
        reach =
          std::min(reach, (data.GetZMin() - axis(0, 1)) / direction(k, 1));
      }
      lo(k, 0) = 0.0;
      hi(k, 0) = (1.0 - 1e-9) * reach;
    }
    example::HostMatrix surface("surface", NumRays, 2);
    auto at = [&](int k, Real t) {
      surface(k, 0) = axis(0, 0) + t * direction(k, 0);
      surface(k, 1) = axis(0, 1) + t * direction(k, 1);
    };
    for (int iteration = 0; iteration < 60; ++iteration) {
      for (int k = 0; k < NumRays; ++k) {
        at(k, 0.5 * (lo(k, 0) + hi(k, 0)));
      }
      const auto values = flux.Psi(surface);
      for (int k = 0; k < NumRays; ++k) {
        const Real mid = 0.5 * (lo(k, 0) + hi(k, 0));
        (values(k, 0) < psi_target ? lo(k, 0) : hi(k, 0)) = mid;
      }
    }
    for (int k = 0; k < NumRays; ++k) {
      at(k, 0.5 * (lo(k, 0) + hi(k, 0)));
    }
    const auto on_surface = flux.Psi(surface);
    Real surface_error = 0.0;
    Real r_min = surface(0, 0), r_max = surface(0, 0);
    Real z_min = surface(0, 1), z_max = surface(0, 1);
    for (int k = 0; k < NumRays; ++k) {
      surface_error =
        std::fmax(surface_error, std::fabs(on_surface(k, 0) - psi_target));
      r_min = std::fmin(r_min, surface(k, 0));
      r_max = std::fmax(r_max, surface(k, 0));
      z_min = std::fmin(z_min, surface(k, 1));
      z_max = std::fmax(z_max, surface(k, 1));
    }
    std::printf("flux surface psi = %.4f: R in [%.4f, %.4f], Z in [%.4f, "
                "%.4f]\n",
                psi_target, r_min, r_max, z_min, z_max);

    // The poloidal field divergence-free: div B = (1/R)(d(dpsi/dR)/dZ -
    // d(dpsi/dZ)/dR), by central differences of the gradient with a step of
    // 1e-3, at the points of the surface.
    const auto right = flux.Gradient(Shifted(surface, Step, 0.0));
    const auto left = flux.Gradient(Shifted(surface, -Step, 0.0));
    const auto up = flux.Gradient(Shifted(surface, 0.0, Step));
    const auto down = flux.Gradient(Shifted(surface, 0.0, -Step));
    Real divergence = 0.0, b_max = 0.0;
    const auto b_at_surface = flux.Gradient(surface);
    for (int k = 0; k < NumRays; ++k) {
      const Real r = surface(k, 0);
      const Real d_z_of_psi_r = (up(k, 0) - down(k, 0)) / (2.0 * Step);
      const Real d_r_of_psi_z = (right(k, 1) - left(k, 1)) / (2.0 * Step);
      divergence =
        std::fmax(divergence, std::fabs(d_z_of_psi_r - d_r_of_psi_z) / r);
      b_max = std::fmax(b_max,
                        std::hypot(b_at_surface(k, 0), b_at_surface(k, 1)) / r);
    }
    std::printf("max |B_pol| on the surface %.3f, max |div B| %.3e\n", b_max,
                divergence);

    // -------------------------------------------------------------------
    // 5. The checks
    //
    // The axis of the Solov'ev equilibrium is at (R0, 0), and psi there is the
    // psi_axis of the file. The outboard point of the surface (the ray with
    // angle 0) has the exact radius R with (R^2 - R0^2)^2 = (psi - psi_axis) /
    // A.
    report.CheckAtMost("magnetic axis: R", std::fabs(axis(0, 0) - R0), AxisTol);
    report.CheckAtMost("magnetic axis: Z", std::fabs(axis(0, 1)), AxisTol);
    report.CheckAtMost("magnetic axis: psi is the file's psi_axis",
                       std::fabs(psi_at_axis - psi_axis), PsiAxisTol);
    report.CheckAtMost("poloidal field from the gradient vs exact", field_error,
                       FieldTol);
    report.CheckAtMost("flux surface: psi equals the target on all rays",
                       surface_error, SurfaceTol);
    const Real r_outboard =
      std::sqrt(R0 * R0 + std::sqrt((psi_target - PsiAxis) / CoefficientA));
    report.CheckAtMost("flux surface: outboard radius vs exact",
                       std::fabs(surface(0, 0) - r_outboard), OutboardTol);
    report.CheckAtMost("div B = 0 on the flux surface", divergence,
                       DivergenceTol);
  }
  return report.Finish();
}
